    "titleGu": "શ્લોક 10",
    "titleHi": "श्लोक 10",
    "titleEn": "Shloka 10",
    "sanskritDevanagari": "दीक्षेति दृढसङ्कल्पः सश्रद्धं निश्चयोऽचलः।\nसम्यक् समर्पणं प्रीत्या निष्ठा व्रतं दृढाश्रयः॥ १०॥",
    "sanskritGujarati": "દીક્ષેતિ દૃઢસઙ્કલ્પઃ સશ્રદ્ધં નિશ્ચયોઽચલઃ।\nસમ્યક્ સમર્પણં પ્રીત્યા નિષ્ઠા વ્રતં દૃઢાશ્રયઃ॥ ૧૦॥",
    "sanskritIast": "Dīkṣheti dṛuḍha-sankalpah sa-shraddham nishchayo’chalaha;\nSamyak samarpaṇam prītyā niṣhṭhā vratam dṛuḍhāshrayaha. 10",
    "meaningGu": "દીક્ષા એટલે દૃઢ સંકલ્પ, શ્રદ્ધાએ સહિત એવો અચળ નિશ્ચય, સમ્યક્ સમર્પણ, પ્રીતિપૂર્વક નિષ્ઠા, વ્રત અને દૃઢ આશરો. (૧૦)",
    "meaningHi": "दीक्षा अर्थात् दृढ संकल्प, श्रद्धा के सहित अविचल निश्चय, सम्यक् समर्पण, प्रीतिपूर्वक निष्ठा, व्रत एवं दृढ आश्रय। (१०)",
    "meaningEn": "‘Diksha’ means firm resolve, unwavering conviction coupled with faith, absolute dedication, loving faith, observances and firm refuge. (10)",
    "meaningMr": "दीक्षा म्हणजे दृढ संकल्प, श्रद्धेसह अचल निश्चय, सम्यक् समर्पण, प्रीतिपूर्वक निष्ठा, व्रत आणि दृढ आश्रय. (10)",
