    "sanskritDevanagari": "शास्त्रेऽस्मिञ्ज्ञापिता स्पष्टम् आज्ञोपासनपद्धतिः।\nपरमात्म-परब्रह्म-सहजानन्द-दर्शिता॥ ११॥",
    "sanskritGujarati": "શાસ્ત્રેઽસ્મિઞ્જ્ઞાપિતા સ્પષ્ટમ્ આજ્ઞોપાસનપદ્ધતિઃ।\nપરમાત્મ-પરબ્રહ્મ-સહજાનન્દ-દર્શિતા॥ ૧૧॥",
    "sanskritIast": "Shāstre’smin gnāpitā spaṣhṭam āgnopāsana-paddhatihi;\nParamātma-Parabrahma-Sahajānanda-darshitā. 11",
    "meaningGu": "આ શાસ્ત્રમાં પરબ્રહ્મ સહજાનંદ પરમાત્માએ દર્શાવેલ આજ્ઞા તથા ઉપાસનાની પદ્ધતિને સ્પષ્ટ રીતે જણાવી છે. (૧૧)",
    "meaningHi": "इस शास्त्र में परब्रह्म सहजानंद परमात्मा के द्वारा दर्शित आज्ञा तथा उपासना की पद्धति स्पष्ट रूप से ज्ञापित की गई है। (११)",
    "meaningEn": "The methods of āgnā and upāsanā revealed by Parabrahman Sahajanand Paramatma are clearly expressed in this shastra. (11)",
    "meaningMr": "या ग्रंथात परब्रह्म परमात्मा सहजानंद स्वामींनी दर्शवलेल्या, आज्ञा तसेच उपासनापद्धतींना स्पष्ट रीतीने समजावल्या आहेत. (11)",
