    "sanskritGujarati": "સત્સઙ્ગાઽધિકૃતઃ સર્વે સર્વે સુખાઽધિકારિણઃ।\nસર્વેઽર્હા બ્રહ્મવિદ્યાયાં નાર્યશ્ચૈવ નરાસ્તથા॥ ૧૨॥",
    "sanskritIast": "Satsangā’dhikṛutah sarve sarve sukhā’dhi-kāriṇaha;\nSarve’rhā brahmavidyāyām nāryash-chaiva narās-tathā. 12",
