    "titleEn": "Shloka 18",
    "sanskritDevanagari": "स्वामिनारायणेऽनन्य-दृढपरमभक्तये।\nगृहीत्वाऽऽश्रयदीक्षाया मन्त्रं सत्सङ्गमाप्नुयात्॥ १८॥",
    "sanskritGujarati": "સ્વામિનારાયણેઽનન્ય-દૃઢપરમભક્તયે।\nગૃહીત્વાઽઽશ્રયદીક્ષાયા મન્ત્રં સત્સઙ્ગમાપ્નુયાત્॥ ૧૮॥",
    "sanskritIast": "Swāminārāyaṇe’nanya-dṛuḍha-parama-bhaktaye;\nGṛuhītvā’shraya-dīkṣhāyā mantram satsangam āpnuyāt. 18",
    "meaningGu": "સ્વામિનારાયણ ભગવાનને વિષે અનન્ય, દૃઢ અને પરમ ભક્તિ માટે આશ્રયદીક્ષામંત્ર ગ્રહણ કરી સત્સંગ પ્રાપ્ત કરવો. (૧૮)",
    "meaningHi": "भगवान श्रीस्वामिनारायण के प्रति अनन्य, दृढ तथा परम भक्ति के लिए आश्रयदीक्षामंत्र ग्रहण करके सत्संग प्राप्त करें। (१८)",
    "meaningEn": "To offer singular, resolute and supreme devotion to Bhagwan Swaminarayan, one should receive the Ashray Diksha Mantra and affiliate with the Satsang. (18)",
    "meaningMr": "स्वामिनारायण भगवंतांविषयी अनन्य, दृढ आणि परम भक्तीसाठी आश्रयदीक्षामंत्र ग्रहण करून सत्संग प्राप्त करावा. (18)",
