    "titleEn": "Shloka 28",
    "sanskritDevanagari": "परित्याज्यं सदा द्यूतं सर्वैः सर्वप्रकारकम्।\nत्यक्तव्यो व्यभिचारश्च नारीभिः पुरुषैस्तथा॥ २८॥",
    "sanskritGujarati": "પરિત્યાજ્યં સદા દ્યૂતં સર્વૈઃ સર્વપ્રકારકમ્।\nત્યક્તવ્યો વ્યભિચારશ્ચ નારીભિઃ પુરુષૈસ્તથા॥ ૨૮॥",
    "sanskritIast": "Pari-tyājyam sadā dyūtam sarvaih sarva-prakārakam;\nTyaktavyo vyabhichārash-cha nārībhih puruṣhais-tathā. 28",
    "meaningGu": "સર્વે સ્ત્રી તથા પુરુષોએ સર્વ પ્રકારના જુગારનો તથા વ્યભિચારનો ત્યાગ કરવો. (૨૮)",
    "meaningHi": "सभी महिलाएँ तथा पुरुष हर प्रकार के जुए तथा व्यभिचार का त्याग करें। (२८)",
    "meaningEn": "All women and men should never engage in any form of gambling or adultery. (28)",
    "meaningMr": "सर्व स्त्री आणि पुरुषांनी सर्व प्रकारच्या जुगारांचा आणि व्यभिचारांचा त्याग करावा. (28)",
