    "sanskritDevanagari": "मांसं मत्स्यं तथाऽण्डानि भक्षयेयुर्न कर्हिचित्।\nपलाण्डुं लशुनं हिङ्गु न च सत्सङ्गिनो जनाः॥ २९॥",
    "sanskritGujarati": "માંસં મત્સ્યં તથાઽણ્ડાનિ ભક્ષયેયુર્ન કર્હિચિત્।\nપલાણ્ડું લશુનં હિઙ્ગુ ન ચ સત્સઙ્ગિનો જનાઃ॥ ૨૯॥",
    "sanskritIast": "Mānsam matsyam tathā’ṇḍāni bhakṣhayeyur na karhichit;\nPalāṇḍum lashunam hingu na cha satsangino janāhā. 29",
    "meaningGu": "સત્સંગી જનોએ ક્યારેય માંસ, માછલી, ઈંડાં તથા ડુંગળી, લસણ, હિંગ ન ખાવાં. (૨૯)",
    "meaningHi": "सत्संगी जन मांस, मछली, अंडे तथा प्याज, लहसुन और हींग कदापि न खाएँ। (२९)",
    "meaningEn": "Satsangis should never eat meat, fish, eggs, onions, garlic or hing. (29)",
    "meaningMr": "सत्संगी जनांनी कधीही मांस, मासे, अंडे तसेच कांदे, लसूण व हिंग खाऊ नये. (29)",
