    "sanskritGujarati": "ચૌર્યં ન કર્હિચિત્ કાર્યં સત્સઙ્ગમાશ્રિતૈર્જનૈઃ।\nધર્માર્થમપિ નો કાર્યં ચોરકાર્યં તુ કર્હિચિત્॥ ૩૧॥",
    "sanskritIast": "Chauryam na karhichit kāryam satsangam āshritair janaihi;\nDharmārtham api no kāryam chora-kāryam tu karhichit. 31",
