    "sanskritGujarati": "મત્વાઽપિ યજ્ઞશેષં ચ વાઽપિ દેવનિવેદિતમ્।\nમાંસં કદાપિ ભક્ષ્યં ન સત્સઙ્ગમાશ્રિતૈર્જનૈઃ॥ ૩૭॥",
    "sanskritIast": "Matvā’pi yagna-sheṣham cha vā’pi deva-niveditam;\nMānsam kadāpi bhakṣhyam na satsangam āshritair-janaihi. 37",
