    "titleGu": "શ્લોક 44",
    "titleHi": "श्लोक 44",
    "titleEn": "Shloka 44",
    "sanskritDevanagari": "भगवान् सर्वकर्ताऽस्ति दयालुः सर्वरक्षकः।\nस एव नाशकः सर्व-सङ्कटानां सदा मम॥ ४४॥",
    "sanskritGujarati": "ભગવાન્ સર્વકર્તાઽસ્તિ દયાલુઃ સર્વરક્ષકઃ।\nસ એવ નાશકઃ સર્વ-સઙ્કટાનાં સદા મમ॥ ૪૪॥",
    "sanskritIast": "Bhagavān sarva-kartā’sti dayāluh sarva-rakṣhakaha;\nSa eva nāshakah sarva-sankaṭānām sadā mama. 44",
    "meaningGu": "ભગવાન સર્વકર્તા છે, દયાળુ છે, સર્વનું રક્ષણ કરનારા છે અને એ જ સદા મારાં સર્વે સંકટોના ટાળનારા છે. (૪૪)",
    "meaningHi": "भगवान सर्वकर्ता हैं, दयालु हैं, सर्व के रक्षक हैं और वे ही सदा मेरे सभी संकटों के नाशक हैं। (४४)",
    "meaningEn": "Bhagwan is the all-doer, compassionate and the protector of all; at all times, he alone is the resolver of all my adversities. (44)",
    "meaningMr": "भगवंत सर्वकर्ता आहेत, दयाळू आहेत, सर्वांचे रक्षण करणारे आहेत आणि तेच सदैव माझ्या सर्व संकटांना टाळणारे आहेत. (44)",
