    "titleGu": "શ્લોક 47",
    "titleHi": "श्लोक 47",
    "titleEn": "Shloka 47",
    "sanskritDevanagari": "यतो मां मिलितः साक्षाद् अक्षरपुरुषोत्तमः।\nनिश्चयेन तरिष्यामि दुःखजातं हि तद्‌बलात्॥ ४७॥",
    "sanskritGujarati": "યતો માં મિલિતઃ સાક્ષાદ્ અક્ષરપુરુષોત્તમઃ।\nનિશ્ચયેન તરિષ્યામિ દુઃખજાતં હિ તદ્‌બલાત્॥ ૪૭॥",
    "sanskritIast": "Yato mām militah sākṣhād Akṣhara-Puruṣhottamaha;\nNishchayena tariṣhyāmi dukha-jātam hi tad balāt. 47",
    "meaningGu": "કારણ કે મને સાક્ષાત્ અક્ષરપુરુષોત્તમ મહારાજ મળ્યા છે. તેમના બળે હું જરૂર દુઃખને તરી જઈશ. (૪૭)",
    "meaningHi": "क्योंकि मुझे साक्षात् श्रीअक्षरपुरुषोत्तम महाराज मिले हैं। उनके बल से मैं निश्चय ही दुःखों को पार कर जाऊँगा। (४७)",
    "meaningEn": "This is because I have attained the manifest form of Akshar-Purushottam Maharaj. With his strength, I will surely overcome misery. (47)",
    "meaningMr": "कारण मला साक्षात अक्षरपुरुषोत्तम महाराज भेटले आहेत. त्यांच्या बळाने मी नक्की दुःखाला तरुन जाईन. (47)",
