    "sanskritDevanagari": "ष्ठीवनं मलमूत्रादिविसर्जनं स्थलेषु च।\nशास्त्रलोकनिषिद्धेषु न कर्तव्यं कदाचन॥ ४९॥",
    "sanskritGujarati": "ષ્ઠીવનં મલમૂત્રાદિવિસર્જનં સ્થલેષુ ચ।\nશાસ્ત્રલોકનિષિદ્ધેષુ ન કર્તવ્યં કદાચન॥ ૪૯॥",
    "sanskritIast": "Ṣhṭhīvanam mala-mūtrādi-visarjanam sthaleṣhu cha;\nShāstra-loka-niṣhiddheṣhu na kartavyam kadāchana. 49",
    "meaningGu": "શાસ્ત્રમાં તથા લોકમાં નિષેધ કર્યો હોય તેવાં સ્થાનોને વિષે ક્યારેય થૂંકવું નહીં તથા મળ-મૂત્રાદિ ન કરવું. (૪૯)",
    "meaningHi": "शास्त्रनिषिद्ध तथा लोकवर्जित स्थानों में कदापि न थूकें तथा मल-मूत्रादि न करें। (४९)",
    "meaningEn": "One should never spit, urinate or defecate in places prohibited by the shastras and society. (49)",
    "meaningMr": "शास्त्रांनी आणि समाजाने निषिद्ध केलेल्या स्थानी कधीही थुंकू नये किंवा मल-मूत्र विसर्जन करू नये. (49)",
