    "sanskritDevanagari": "शुद्धिः सर्वविधा पाल्या बाह्या चाऽऽभ्यन्तरा सदा।\nशुद्धिप्रियः प्रसीदेच्च शुद्धिमति जने हरिः॥ ५०॥",
    "sanskritGujarati": "શુદ્ધિઃ સર્વવિધા પાલ્યા બાહ્યા ચાઽઽભ્યન્તરા સદા।\nશુદ્ધિપ્રિયઃ પ્રસીદેચ્ચ શુદ્ધિમતિ જને હરિઃ॥ ૫૦॥",
    "sanskritIast": "Shuddhih sarvavidhā pālyā bāhyā chā’bhyantarā sadā;\nShuddhi-priyah prasīdech-cha shuddhi-mati jane Harihi. 50",
    "meaningGu": "બાહ્ય અને આંતરિક એમ સર્વ પ્રકારની શુદ્ધિનું પાલન કરવું. શ્રીહરિને શુદ્ધિ પ્રિય છે અને શુદ્ધિવાળા મનુષ્યની ઉપર તેઓ પ્રસન્ન થાય છે. (૫૦)",
    "meaningHi": "सभी प्रकार की बाह्य और आंतरिक शुद्धि का सदा पालन करें। श्रीहरि को शुद्धि प्रिय है और शुद्धियुक्त मनुष्य पर वे प्रसन्न होते हैं। (५०)",
    "meaningEn": "One should observe all forms of external and internal purity. Shri Hari loves purity and is pleased with those who are pure. (50)",
    "meaningMr": "बाह्य तसेच आंतरिक अशा सर्व प्रकारच्या शुद्धीचे पालन करावे. श्रीहरींना शुद्धी प्रिय आहे आणि शुद्ध मनष्यावर ते प्रसन्न होतात. (50)",
