    "sanskritDevanagari": "सत्सङ्गिभिः प्रबोद्धव्यं पूर्वं सूर्योदयात् सदा।\nततः स्नानादिकं कृत्वा धर्तव्यं शुद्धवस्त्रकम्॥ ५१॥",
    "sanskritGujarati": "સત્સઙ્ગિભિઃ પ્રબોદ્ધવ્યં પૂર્વં સૂર્યોદયાત્ સદા।\nતતઃ સ્નાનાદિકં કૃત્વા ધર્તવ્યં શુદ્ધવસ્ત્રકમ્॥ ૫૧॥",
    "sanskritIast": "Satsangibhih praboddhavyam pūrvam sūryodayāt sadā;\nTatah snānādikam kṛutvā dhartavyam shuddha vastrakam. 51",
