    "sanskritDevanagari": "पूर्वस्यामुत्तरस्यां वा दिशि कृत्वा मुखं ततः।\nशुद्धाऽऽसनोपविष्टः सन् नित्यपूजां समाचरेत्॥ ५२॥",
    "sanskritGujarati": "પૂર્વસ્યામુત્તરસ્યાં વા દિશિ કૃત્વા મુખં તતઃ।\nશુદ્ધાઽઽસનોપવિષ્ટઃ સન્ નિત્યપૂજાં સમાચરેત્॥ ૫૨॥",
    "sanskritIast": "Pūrvasyām uttarasyām vā dishi kṛutvā mukham tataha;\nShuddhā’sanopaviṣhṭah san-nitya-pūjām samācharet. 52",
    "meaningGu": "ત્યાર બાદ પૂર્વ દિશામાં અથવા ઉત્તર દિશામાં મુખ રાખી, શુદ્ધ આસન ઉપર બેસી નિત્યપૂજા કરવી. (૫૨)",
    "meaningHi": "तत्पश्चात् पूर्व अथवा उत्तर दिशा में मुख रखकर शुद्ध आसन पर बैठकर नित्यपूजा करें। (५२)",
    "meaningEn": "Thereafter, one should sit on a clean āsan and perform personal daily puja facing east or north. (52)",
    "meaningMr": "त्यानंतर शुद्ध आसनावर पूर्वाभिमुख किंवा उत्तराभिमुख बसून नित्यपूजा करावी. (52)",
