    "sanskritDevanagari": "केवलं चन्द्रकः स्त्रीभिः कर्तव्यस्तिलकं नहि।\nकुङ्कुमद्रव्यतो भाले स्मरन्तीभिर्हरिं गुरुम्॥ ५५॥",
    "sanskritGujarati": "કેવલં ચન્દ્રકઃ સ્ત્રીભિઃ કર્તવ્યસ્તિલકં નહિ।\nકુઙ્કુમદ્રવ્યતો ભાલે સ્મરન્તીભિર્હરિં ગુરુમ્॥ ૫૫॥",
    "sanskritIast": "Kevalam chandrakah strībhih kartavyas-tilakam na hi;\nKumkuma dravyato bhāle smarantībhir harim gurum. 55",
