    "sanskritDevanagari": "उत्तिष्ठ सहजानन्द श्रीहरे पुरुषोत्तम।\nगुणातीताऽक्षर ब्रह्मन्नुत्तिष्ठ कृपया गुरो॥ ६४॥",
