    "titleGu": "શ્લોક 69",
    "titleHi": "श्लोक 69",
    "titleEn": "Shloka 69",
    "sanskritDevanagari": "साष्टाङ्गा दण्डवत् कार्याः प्रणामाः पुरुषैस्ततः।\nनारीभिस्तूपविश्यैव पञ्चाङ्गा दासभावतः॥ ६९॥",
    "sanskritGujarati": "સાષ્ટાઙ્ગા દણ્ડવત્ કાર્યાઃ પ્રણામાઃ પુરુષૈસ્તતઃ।\nનારીભિસ્તૂપવિશ્યૈવ પઞ્ચાઙ્ગા દાસભાવતઃ॥ ૬૯॥",
    "sanskritIast": "Sāṣhṭāngā daṇḍavat kāryāh praṇāmāh puruṣhais-tataha;\nNārībhis-tūpavishyaiva panchāngā dāsa-bhāvataha. 69",
    "meaningGu": "ત્યાર બાદ દાસભાવે પુરુષોએ સાષ્ટાંગ દંડવત્ પ્રણામ કરવા અને સ્ત્રીઓએ બેસીને પંચાંગ પ્રણામ કરવા. (૬૯)",
    "meaningHi": "तत्पश्चात् दासभाव से पुरुष साष्टांग दंडवत् प्रणाम करें और महिलाएँ बैठकर पंचांग प्रणाम करें। (६९)",
    "meaningEn": "Thereafter, with dāsbhāv, males should perform sāshtāng dandvat pranāms and females should sit and offer panchāng pranāms. (69)",
    "meaningMr": "त्यानंतर पुरुषांनी दास्यभावाने साष्टांग दंडवत प्रणाम करावेत आणि स्त्रियांनी बसूनच पंचांग प्रणाम करावेत. (69)",
