    "titleEn": "Shloka 71",
    "sanskritDevanagari": "दिव्यभावेन भक्त्या च तदनु प्रार्थयेज्जपन्।\nस्वामिनारायणं मन्त्रं शुभसङ्कल्पपूर्तये॥ ७१॥",
    "sanskritGujarati": "દિવ્યભાવેન ભક્ત્યા ચ તદનુ પ્રાર્થયેજ્જપન્।\nસ્વામિનારાયણં મન્ત્રં શુભસઙ્કલ્પપૂર્તયે॥ ૭૧॥",
    "sanskritIast": "Divya-bhāvena bhaktyā cha tad-anu prārthayej-japan;\nSwāminārāyaṇam mantram shubha-sankalpa-pūrtaye. 71",
    "meaningGu": "ત્યાર બાદ સ્વામિનારાયણ મંત્રનો જપ કરતાં શુભ સંકલ્પોની પૂર્તિ માટે દિવ્યભાવ અને ભક્તિએ સહિત પ્રાર્થના (ધૂન) કરવી. (૭૧)",
    "meaningHi": "तत्पश्चात् शुभ संकल्पों की पूर्ति के लिए स्वामिनारायण मंत्र जपते हुए दिव्यभाव और भक्ति से प्रार्थना करें। (७१)",
    "meaningEn": "Then, to fulfil one’s noble wishes, one should pray with divyabhāv and devotion while chanting the Swaminarayan mantra (dhun). (71)",
    "meaningMr": "त्यानंतर स्वामिनारायण मंत्राचा जप करत शुभ संकल्पांच्या पूर्तीसाठी, दिव्यभाव आणि भक्तीसह प्रार्थना (धून) करावी. (71)",
