    "sanskritDevanagari": "भक्तितः पूजयित्वैवम् अक्षरपुरुषोत्तमम्।\nपुनरागममन्त्रेण प्रस्थापयेन्निजात्मनि॥ ७२॥",
    "sanskritGujarati": "ભક્તિતઃ પૂજયિત્વૈવમ્ અક્ષરપુરુષોત્તમમ્।\nપુનરાગમમન્ત્રેણ પ્રસ્થાપયેન્નિજાત્મનિ॥ ૭૨॥",
    "sanskritIast": "Bhaktitah pūjayitvaivam Akṣhara-Puruṣhottamam;\nPunar-āgama-mantreṇa prasthāpayen-nijātmani. 72",
    "meaningGu": "આ રીતે ભક્તિભાવે પૂજા કરીને પુનરાગમન મંત્રથી અક્ષરપુરુષોત્તમ મહારાજને પોતાના આત્માને વિષે પધરાવવા. (૭૨)",
    "meaningHi": "इस प्रकार भक्तिभाव से पूजा करके पुनरागमन मंत्र के द्वारा अक्षरपुरुषोत्तम महाराज को अपनी आत्मा में स्थापित करें। (७२)",
    "meaningEn": "After devoutly performing puja in this way, one should re-install Akshar-Purushottam Maharaj within one’s ātmā by reciting the Punaragaman Mantra. (72)",
    "meaningMr": "अशा रीतीने भक्तिभावाने पूजा करून पुनरागमन मंत्राद्वारे अक्षरपुरुषोत्तम महाराजांची स्वतःच्या आत्म्यामध्ये स्थापना करावी. (72)",
