    "titleEn": "Shloka 75",
    "sanskritDevanagari": "तदनु प्रणमेद् भक्तान् आदरान्नम्रभावतः।\nएवं पूजां समाप्यैव कुर्यात् स्वव्यावहारिकम्॥ ७५॥",
    "sanskritGujarati": "તદનુ પ્રણમેદ્ ભક્તાન્ આદરાન્નમ્રભાવતઃ।\nએવં પૂજાં સમાપ્યૈવ કુર્યાત્ સ્વવ્યાવહારિકમ્॥ ૭૫॥",
    "sanskritIast": "Tad-anu praṇamed bhaktān ādarān-namra-bhāvatah;\nEvam pūjām samāpyaiva kuryāt sva-vyāvahārikam. 75",
    "meaningGu": "ત્યાર બાદ આદર અને નમ્રભાવે ભક્તોને પ્રણામ કરવા. આ રીતે પૂજા કરીને પછી જ પોતાના વ્યવહારનું કાર્ય કરવું. (૭૫)",
    "meaningHi": "तत्पश्चात् आदर और नम्रभाव से भक्तों को प्रणाम करें। इस प्रकार पूजा करने के बाद ही अपना व्यावहारिक कार्य करें। (७५)",
    "meaningEn": "Thereafter, one should bow to devotees with reverence and humility. Only after performing puja in this way should one engage in one’s daily activities. (75)",
    "meaningMr": "त्यानंतर आदरपूर्वक नम्रभावाने भक्तांना प्रणाम करावा. अशा रीतीने पूजा केल्यानंतरच स्वतःचे व्यवहारकार्य करावे. (75)",
