    "titleGu": "શ્લોક 76",
    "titleHi": "श्लोक 76",
    "titleEn": "Shloka 76",
    "sanskritDevanagari": "भोज्यं नैव न पेयं वा विना पूजां जलादिकम्।\nप्रवासगमने चाऽपि पूजां नैव परित्यजेत्॥ ७६॥",
    "sanskritGujarati": "ભોજ્યં નૈવ ન પેયં વા વિના પૂજાં જલાદિકમ્।\nપ્રવાસગમને ચાઽપિ પૂજાં નૈવ પરિત્યજેત્॥ ૭૬॥",
    "sanskritIast": "Bhojyam naiva na peyam vā vinā pūjām jalādikam;\nPravāsa-gamane chā’pi pūjām naiva pari-tyajet. 76",
    "meaningGu": "પૂજા કર્યા વિના જમવું નહીં ને પાણી વગેરે પણ ન પીવું. પ્રવાસે ગયા હોઈએ તો પણ પૂજાનો ત્યાગ ન કરવો. (૭૬)",
    "meaningHi": "पूजा किए बिना भोजन न करें और जल आदि भी न पीएँ। यात्रा के दौरान भी पूजा का त्याग न करें। (७६)",
    "meaningEn": "One should not eat food or even drink water or other liquids without performing puja. One should not give up one’s puja even during outings. (76)",
    "meaningMr": "पूजा केल्याशिवाय खाऊ नये आणि पाणीही पिऊ नये. प्रवासात देखील पूजेचा त्याग करू नये. (76)",
