    "sanskritDevanagari": "स्वीयपूजा स्वतन्त्रा तु सर्वै रक्ष्या गृहे पृथक्।\nजन्मनो दिवसादेव पूजा ग्राह्या स्वसंततेः॥ ७८॥",
    "sanskritGujarati": "સ્વીયપૂજા સ્વતન્ત્રા તુ સર્વૈ રક્ષ્યા ગૃહે પૃથક્।\nજન્મનો દિવસાદેવ પૂજા ગ્રાહ્યા સ્વસંતતેઃ॥ ૭૮॥",
    "sanskritIast": "Svīyapūjā svatantrā tu sarvai rakṣhyā gṛuhe pṛuthak;\nJanmano divasād eva pūjā grāhyā sva-santatehe. 78",
    "meaningGu": "ઘરમાં પ્રત્યેક સત્સંગીએ પોતાની સ્વતંત્ર પૂજા રાખવી. વળી પુત્ર કે પુત્રીનો જન્મ થાય તે દિવસથી જ સંતાન માટે પૂજા લઈ લેવી. (૭૮)",
    "meaningHi": "घर में प्रत्येक सत्संगी अपनी स्वतंत्र पूजा रखे। पुत्र या पुत्री का जन्म हो उसी दिन से अपनी संतान के लिए पूजा-सामग्री ले लें। (७८)",
    "meaningEn": "Every satsangi in a household should keep their own separate puja. Moreover, one should acquire a puja for a child on the same day that he or she is born. (78)",
    "meaningMr": "घरातील प्रत्येक सत्संगीनी स्वतःची स्वतंत्र पूजा ठेवावी. तसेच ज्या दिवशी पुत्र किंवा पुत्रीचा जन्म होईल, त्या दिवशीच मुलांसाठी पूजा घेऊन ठेवावी. (78)",
