    "sanskritDevanagari": "प्रातः प्रतिदिनं सायं सर्वैः सत्सङ्गिभिर्जनैः।\nआरार्तिक्यं विधातव्यं सस्तुति गृहमन्दिरे॥ ८१॥",
    "sanskritGujarati": "પ્રાતઃ પ્રતિદિનં સાયં સર્વૈઃ સત્સઙ્ગિભિર્જનૈઃ।\nઆરાર્તિક્યં વિધાતવ્યં સસ્તુતિ ગૃહમન્દિરે॥ ૮૧॥",
    "sanskritIast": "Prātah prati-dinam sāyam sarvaih satsangibhir janaihi;\nĀrārtikyam vidhātavyam sa-stuti gṛuha-mandire. 81",
