    "titleEn": "Shloka 83",
    "sanskritDevanagari": "यैव रसवती पक्वा मन्दिरे तां निवेदयेत्।\nउच्चार्य प्रार्थनं भक्त्या ततः प्रसादितं जमेत्॥ ८३॥",
    "sanskritGujarati": "યૈવ રસવતી પક્વા મન્દિરે તાં નિવેદયેત્।\nઉચ્ચાર્ય પ્રાર્થનં ભક્ત્યા તતઃ પ્રસાદિતં જમેત્॥ ૮૩॥",
    "sanskritIast": "Yaiva rasavatī pakvā mandire tām nivedayet;\nUchchārya prārthanam bhaktyā tatah prasāditam jamet. 83",
    "meaningGu": "જે રસોઈ બનાવી હોય તે મંદિરમાં ધરાવવી અને પ્રસાદીભૂત થયેલ ભોજન ભક્તિભાવપૂર્વક પ્રાર્થના બોલીને પછી જમવું. (૮૩)",
    "meaningHi": "जो भोजन बनाया हो उसे घरमंदिर में निवेदित करें। तत्पश्चात् भक्तिभाव से प्रार्थना बोलकर प्रासादिक भोजन ग्रहण करें। (८३)",
    "meaningEn": "Offer whatever food has been prepared [to the murtis] in the ghar mandir and after devoutly reciting prayers, eat the sanctified meal. (83)",
    "meaningMr": "केलेल्या स्वयंपाकाचा नैवेद्य मंदिरात दाखवून, प्रसादिभूत झालेले भोजन भक्तिभावपूर्वक प्रार्थना म्हणून ग्रहण करावे. (83)",
