    "titleEn": "Shloka 85",
    "sanskritDevanagari": "कीर्तनं वा जपं कुर्यात् स्मृत्यादि वा यथारुचि।\nगृहमन्दिरमास्थाय भावतः स्थिरचेतसा॥ ८५॥",
    "sanskritGujarati": "કીર્તનં વા જપં કુર્યાત્ સ્મૃત્યાદિ વા યથારુચિ।\nગૃહમન્દિરમાસ્થાય ભાવતઃ સ્થિરચેતસા॥ ૮૫॥",
    "sanskritIast": "Kīrtanam vā japam kuryāt smṛutyādi vā yathā-ruchi;\nGṛuha-mandiram āsthāya bhāvatah sthira-chetasā. 85",
    "meaningGu": "ઘરમંદિરમાં બેસીને ભાવે કરીને સ્થિર ચિત્તે કીર્તન, જપ કે સ્મૃતિ વગેરે પોતાની રુચિ અનુસાર કરવું. (૮૫)",
    "meaningHi": "घरमंदिर में बैठकर स्थिर चित्त से भावपूर्वक कीर्तन, जप या स्मृति इत्यादि अपनी रुचि के अनुसार करें। (८५)",
    "meaningEn": "While sitting in front of the ghar mandir, one should, with devout feelings and concentration, sing kirtans, chant and engage in smruti or other acts of devotion according to one’s preferences. (85)",
    "meaningMr": "घरमंदिरात बसून भावपूर्वक, स्थिर चित्ताने कीर्तन, जप किंवा स्मृती वगैरे स्वतःच्या आवडीनुसार करावे. (85)",
