    "sanskritDevanagari": "संभूय प्रत्यहं कार्या गृहसभा गृहस्थितैः।\nकर्तव्यं भजनं गोष्ठिः शास्त्रपाठादि तत्र च॥ ८६॥",
    "sanskritGujarati": "સંભૂય પ્રત્યહં કાર્યા ગૃહસભા ગૃહસ્થિતૈઃ।\nકર્તવ્યં ભજનં ગોષ્ઠિઃ શાસ્ત્રપાઠાદિ તત્ર ચ॥ ૮૬॥",
    "sanskritIast": "Sambhūya pratyaham kāryā gṛuha-sabhā gṛuhasthitaihi;\nKartavyam bhajanam goṣhṭhih shāstra-pāṭhādi tatra cha. 86",
    "meaningGu": "ઘરના સભ્યોએ ભેગા થઈ રોજ ઘરસભા કરવી અને તેમાં ભજન, ગોષ્ઠિ તથા શાસ્ત્રોનું વાંચન ઇત્યાદિ કરવું. (૮૬)",
    "meaningHi": "घर के सदस्य एकत्र होकर प्रतिदिन घरसभा करें और उसमें भजन, गोष्ठी, शास्त्रों का पठन इत्यादि करें। (८६)",
    "meaningEn": "Family members should gather daily for ghar sabhā and engage in bhajan, discussions, scriptural reading and other devotional activities. (86)",
    "meaningMr": "घरातील सदस्यांनी एकत्र होऊन रोज घरसभा करावी आणि त्यात भजन, सत्संग-गोष्टी तसेच ग्रंथवाचन इत्यादी करावे. (86)",
