    "sanskritDevanagari": "वर्तत उत्तमो भक्तो ब्रह्म भगवतोऽक्षरम्।\nनित्यं मायापरं नित्यं हरिसेवारतं यतः॥ ८९॥",
    "sanskritGujarati": "વર્તત ઉત્તમો ભક્તો બ્રહ્મ ભગવતોઽક્ષરમ્।\nનિત્યં માયાપરં નિત્યં હરિસેવારતં યતઃ॥ ૮૯॥",
    "sanskritIast": "Vartata uttamo bhakto Brahma Bhagavato’kṣharam;\nNityam māyā-param nityam Hari-sevāratam yataha. 89",
    "meaningGu": "અક્ષરબ્રહ્મ ભગવાનના ઉત્તમ ભક્ત છે, કારણ કે તેઓ નિત્ય માયાપર છે અને નિત્ય ભગવાનની સેવામાં રમમાણ હોય છે. (૮૯)",
    "meaningHi": "अक्षरब्रह्म भगवान के उत्तम भक्त हैं। क्योंकि वे नित्य माया से परे हैं और नित्य भगवान की सेवा में रत हैं। (८९)",
    "meaningEn": "Aksharbrahman is Bhagwan’s supreme devotee because he eternally transcends māyā and is forever engrossed in Bhagwan’s service. (89)",
    "meaningMr": "अक्षरब्रह्म भगवंतांचे उत्तम भक्त आहेत, कारण की ते नित्य मायातीत आहेत आणि नित्य भगवंतांच्या सेवेत रममाण असतात. (89)",
