    "sanskritDevanagari": "एवमेव गृहाद्येषु कृतेषु मन्दिरेष्वपि।\nमध्ये प्रस्थाप्यते नित्यं साऽक्षरः पुरुषोत्तमः॥ ९२॥",
    "sanskritGujarati": "એવમેવ ગૃહાદ્યેષુ કૃતેષુ મન્દિરેષ્વપિ।\nમધ્યે પ્રસ્થાપ્યતે નિત્યં સાઽક્ષરઃ પુરુષોત્તમઃ॥ ૯૨॥",
    "sanskritIast": "Evam eva gṛuhādyeṣhu kṛuteṣhu mandireṣhvapi;\nMadhye prasthāpyate nityam sā’kṣharah Puruṣhottamaha. 92",
    "meaningGu": "એ જ રીતે ઘર આદિ સ્થળોને વિષે કરેલ મંદિરોમાં પણ મધ્યમાં હંમેશાં અક્ષરબ્રહ્મ સહિત પુરુષોત્તમ ભગવાનને પ્રસ્થાપિત કરવામાં આવે છે. (૯૨)",
    "meaningHi": "उसी प्रकार घर आदि स्थानों में निर्मित मंदिरों में भी मध्य में सदा अक्षरब्रह्म सहित पुरुषोत्तम भगवान को स्थापित किया जाता है। (९२)",
    "meaningEn": "Similarly, Aksharbrahman and Purushottam Bhagwan are also always consecrated in the central shrines of mandirs in homes and other places. (92)",
    "meaningMr": "अशाच रीतीने घरी किंवा अन्य स्थळी असलेल्या मंदिरांमध्ये देखील मधोमध नेहमी अक्षरब्रह्मांसहित पुरुषोत्तम भगवंत प्रस्थापित केले जातात. (92)",
