    "sanskritDevanagari": "प्रातः सायं यथाकालं सर्वसत्सङ्गिभिर्जनैः।\nनिकटं मन्दिरं गम्यं भक्त्या दर्शाय प्रत्यहम्॥ ९३॥",
    "sanskritGujarati": "પ્રાતઃ સાયં યથાકાલં સર્વસત્સઙ્ગિભિર્જનૈઃ।\nનિકટં મન્દિરં ગમ્યં ભક્ત્યા દર્શાય પ્રત્યહમ્॥ ૯૩॥",
    "sanskritIast": "Prātah sāyam yathā-kālam sarva-satsangibhir janaihi;\nNikaṭam mandiram gamyam bhaktyā darshāya pratyaham. 93",
    "meaningGu": "સર્વે સત્સંગીઓએ સવારે, સાંજે અથવા પોતાના અનુકૂળ સમયે પ્રતિદિન ભક્તિએ કરીને સમીપે આવેલ મંદિરે દર્શને જવું. (૯૩)",
    "meaningHi": "सभी सत्संगी प्रातःकाल, संध्या समय अथवा अपने अनुकूल समय पर प्रतिदिन भक्तिपूर्वक समीपवर्ती मंदिर में दर्शन करने जाएँ। (९३)",
    "meaningEn": "Daily, in the morning, evening or at another convenient time, all satsangis should devoutly go to a nearby mandir for darshan. (93)",
    "meaningMr": "सर्व सत्संगींनी सकाळी, संध्याकाळी अथवा स्वतःच्या सोयीने प्रतिदिन भक्तिभावाने, जवळपास असलेल्या मंदिरात दर्शनाला जावे. (93)",
