    "sanskritDevanagari": "सत्सङ्गदृढतार्थं हि सभार्थमन्तिके स्थितम्।\nगन्तव्यं प्रतिसप्ताहं मन्दिरं वाऽपि मण्डलम्॥ ९५॥",
    "sanskritGujarati": "સત્સઙ્ગદૃઢતાર્થં હિ સભાર્થમન્તિકે સ્થિતમ્।\nગન્તવ્યં પ્રતિસપ્તાહં મન્દિરં વાઽપિ મણ્ડલમ્॥ ૯૫॥",
    "sanskritIast": "Satsanga-dṛuḍhatārtham hi sabhārtham antike sthitam;\nGantavyam prati-saptāham mandiram vā’pi maṇḍalam. 95",
