    "sanskritDevanagari": "स एकः परमोपास्य इष्टदेवो हि नः सदा।\nतस्यैव सर्वदा भक्तिः कर्तव्याऽनन्यभावतः॥ ९७॥",
    "sanskritGujarati": "સ એકઃ પરમોપાસ્ય ઇષ્ટદેવો હિ નઃ સદા।\nતસ્યૈવ સર્વદા ભક્તિઃ કર્તવ્યાઽનન્યભાવતઃ॥ ૯૭॥",
    "sanskritIast": "Sa ekah paramopāsya iṣhṭa-devo hi nah sadā;\nTasyaiva sarvadā bhaktih kartavyā’nanya-bhāvataha. 97",
