    "titleEn": "Shloka 100",
    "sanskritDevanagari": "एक एवेष्टदेवो नः एक एव गुरुस्तथा।\nएकश्चैवाऽपि सिद्धान्त एवं नः एकता सदा॥ १००॥",
    "sanskritGujarati": "એક એવેષ્ટદેવો નઃ એક એવ ગુરુસ્તથા।\nએકશ્ચૈવાઽપિ સિદ્ધાન્ત એવં નઃ એકતા સદા॥ ૧૦૦॥",
    "sanskritIast": "Eka eveṣhṭa-devo nah eka eva gurus-tathā;\nEkash-chaivā’pi siddhānta evam nah ekatā sadā. 100",
    "meaningGu": "આપણા ઇષ્ટદેવ એક જ છે, ગુરુ એક જ છે અને સિદ્ધાંત પણ એક જ છે એમ આપણી સદા એકતા છે. (૧૦૦)",
    "meaningHi": "हमारे इष्टदेव एक ही हैं, गुरु एक ही हैं और सिद्धांत भी एक ही है। इस प्रकार हमारी सदैव एकता है। (१००)",
    "meaningEn": "Our ishtadev is the same, our guru is the same and our siddhānt is also the same – thus, we are always united. (100)",
    "meaningMr": "आपले इष्टदैवत एकच आहेत, गुरु एकच आहेत आणि सिद्धांतही एकच आहे. अशी आपली सदैव एकता आहे. (100)",
