    "sanskritDevanagari": "सिद्धान्तं सुविजानीयाद् अक्षरपुरुषोत्तमम्।\nब्रह्मविद्यात्मकं दिव्यं वैदिकं च सनातनम्॥ १०१॥",
    "sanskritGujarati": "સિદ્ધાન્તં સુવિજાનીયાદ્ અક્ષરપુરુષોત્તમમ્।\nબ્રહ્મવિદ્યાત્મકં દિવ્યં વૈદિકં ચ સનાતનમ્॥ ૧૦૧॥",
    "sanskritIast": "Siddhāntam suvijānīyād Akṣhara-Puruṣhottamam;\nBrahmavidyātmakam divyam vaidikam cha sanātanam. 101",
    "meaningGu": "બ્રહ્મવિદ્યારૂપ, વૈદિક અને સનાતન એવા દિવ્ય અક્ષરપુરુષોત્તમ સિદ્ધાંતને જાણવો. (૧૦૧)",
    "meaningHi": "ब्रह्मविद्यारूप, वैदिक, सनातन एवं दिव्य अक्षरपुरुषोत्तम सिद्धांत को समझें। (१०१)",
    "meaningEn": "One should know [and realize] the divine Akshar-Purushottam siddhānt, which is Vedic, eternal and the form of brahmavidyā. (101)",
    "meaningMr": "ब्रह्मविद्यारूप, वैदिक आणि सनातन अशा दिव्य अक्षरपुरुषोत्तम सिद्धांताला जाणावे. (101)",
