    "titleGu": "શ્લોક 104",
    "titleHi": "श्लोक 104",
    "titleEn": "Shloka 104",
    "sanskritDevanagari": "तेषु मायापरौ नित्यम् अक्षरपुरुषोत्तमौ।\nजीवानामीश्वराणां च मुक्तिस्तद्योगतो भवेत्॥ १०४॥",
    "sanskritGujarati": "તેષુ માયાપરૌ નિત્યમ્ અક્ષરપુરુષોત્તમૌ।\nજીવાનામીશ્વરાણાં ચ મુક્તિસ્તદ્યોગતો ભવેત્॥ ૧૦૪॥",
    "sanskritIast": "Teṣhu māyā-parau nityam Akṣhara-Puruṣhottamau;\nJīvānām-īshvarāṇām cha muktis-tad-yogato bhavet. 104",
    "meaningGu": "તેમાં અક્ષર અને પુરુષોત્તમ એ બે સદાય માયાથી પર છે અને જીવો તથા ઈશ્વરોની મુક્તિ તેમના યોગથી થાય છે. (૧૦૪)",
    "meaningHi": "उसमें अक्षर और पुरुषोत्तम ये दो सदैव माया से परे हैं, और उनके योग से जीवों तथा ईश्वरों की मुक्ति होती है। (१०४)",
    "meaningEn": "Among these entities, Akshar and Purushottam are the two who are eternally beyond māyā. Jivas and ishwars attain moksha by associating with them. (104)",
    "meaningMr": "त्यात अक्षर आणि पुरुषोत्तम हे दोघेही सदैव मायातीत आहेत आणि जीव तथा ईश्वरांची मुक्ती त्यांच्या योगाने होते. (104)",
