    "sanskritDevanagari": "परमात्मा परब्रह्म परं ब्रह्माऽक्षरात् सदा।\nब्रह्माऽपि सेवते तं च दासभावेन सर्वदा॥ १०५॥",
    "sanskritGujarati": "પરમાત્મા પરબ્રહ્મ પરં બ્રહ્માઽક્ષરાત્ સદા।\nબ્રહ્માઽપિ સેવતે તં ચ દાસભાવેન સર્વદા॥ ૧૦૫॥",
    "sanskritIast": "Paramātmā Parabrahma param Brahmā’kṣharāt sadā;\nBrahmā’pi sevate tam cha dāsa-bhāvena sarvadā. 105",
    "meaningGu": "પરમાત્મા પરબ્રહ્મ સદા અક્ષરબ્રહ્મથી પર છે અને અક્ષરબ્રહ્મ પણ તે પરમાત્માની નિત્ય દાસભાવે સેવા કરે છે. (૧૦૫)",
    "meaningHi": "परमात्मा परब्रह्म सदैव अक्षरब्रह्म से परे हैं और अक्षरब्रह्म भी दासभाव से सर्वदा उनकी सेवा करते हैं। (१०५)",
    "meaningEn": "Paramatma Parabrahman is forever superior to Aksharbrahman. Furthermore, even Aksharbrahman eternally serves Paramatma with dāsbhāv. (105)",
    "meaningMr": "परमात्मा परब्रह्म सदा अक्षरब्रह्मांहून अतीत आहेत आणि अक्षरब्रह्मही त्या परमात्म्याची नित्य दास्यभावाने सेवा करतात. (105)",
