    "sanskritDevanagari": "ब्रह्माऽक्षरगुरुद्वारा भगवान् प्रकटः सदा।\nसहितः सकलैश्वर्यैः परमाऽऽनन्दमर्पयन्॥ १०७॥",
    "sanskritGujarati": "બ્રહ્માઽક્ષરગુરુદ્વારા ભગવાન્ પ્રકટઃ સદા।\nસહિતઃ સકલૈશ્વર્યૈઃ પરમાઽઽનન્દમર્પયન્॥ ૧૦૭॥",
    "sanskritIast": "Brahmā’kṣhara-guru-dvārā Bhagavān prakaṭah sadā;\nSahitah sakalaishvaryaih paramā’nandam arpayan. 107",
    "meaningGu": "અક્ષરબ્રહ્મસ્વરૂપ ગુરુ દ્વારા ભગવાન પોતાનાં સકળ ઐશ્વર્યો સહિત, પરમાનંદ અર્પતાં થકાં સદાય પ્રગટ રહે છે. (૧૦૭)",
    "meaningHi": "अक्षरब्रह्मस्वरूप गुरु के द्वारा भगवान अपने संपूर्ण ऐश्वर्य के साथ, परमानंद प्रदान करते हुए सदा प्रकट रहते हैं । (१०७)",
    "meaningEn": "Through the Aksharbrahman guru, Bhagwan always remains present with all of his divinity and bestows utmost bliss. (107)",
    "meaningMr": "अक्षरब्रह्मस्वरूप गुरूंद्वारे भगवान स्वतःच्या समग्र ऐश्वर्यांसह, परमानंद अर्पण करीत सदैव प्रकट राहतात. (107)",
